static lstr L7781 = {-1, 1132, "// std/option: helpers over the prelude Option.\012\012export function map<T, U, effect E>(option: Option<T>, f: (value: T) => U uses E): Option<U> uses alloc, E {\012  return match (option) {\012    Some(value) => Some(f(value))\012    None => None\012  }\012}\012\012export function andThen<T, U, effect E>(option: Option<T>, f: (value: T) => Option<U> uses E): Option<U> uses E {\012  return match (option) {\012    Some(value) => f(value)\012    None => None\012  }\012}\012\012export function withDefault<T>(option: Option<T>, fallback: T): T from option {\012  return match (option) {\012    Some(value) => value\012    None => copy(fallback)\012  }\012}\012\012export function orElse<T, effect E>(option: Option<T>, f: () => Option<T> uses E): Option<T> from option uses E {\012  return match (option) {\012    Some(_) => option\012    None => f()\012  }\012}\012\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> from option uses alloc {\012  return match (option) {\012    Some(value) => Ok(value)\012    None => Err(copy(error))\012  }\012}\012"};
static lstr L7782 = {-1, 10, "std/random"};
static lstr L7783 = {-1, 1807, "// std/random: a seeded generator, SplitMix64. The same seed gives the same numbers on every\012// run and every platform. It is fast and small and it is not for cryptography.\012\012import * as Arrays from \"std/array\"\012import * as Int from \"std/int\"\012import * as Ranges from \"std/range\"\012import * as U64 from \"std/u64\"\012import * as Float from \"std/float\"\012import * as Entropy from \"std/internal/entropy\"\012\012export struct Random {\012  state: u64\012}\012\012export function seeded(seed: int): Random {\012  return Random { state: U64.wrap(seed) }\012}\012\012export function fromSystem(): Random uses io {\012  return seeded(Entropy.seed())\012}\012\012export function nextBits(mutable random: Random): u64 {\012  random.state += 0x9E3779B97F4A7C15\012  let mixed = random.state\012  mixed = (mixed ^ (mixed >> 30)) * 0xBF58476D1CE4E5B9\012  mixed = (mixed ^ (mixed >> 27)) * 0x94D049BB133111EB\012  return mixed ^ (mixed >> 31)\012}\012\012export function nextInt(mutable random: Random, low: int, high: int): Option<int> {\012  if (low >= high) {\012    return None\012  }\012  const span = U64.wrap(high) - U64.wrap(low)\012  if (span == 0) {\012    return Some(low)\012  }\012  const limit = (0 - span) % span\012  let bits = nextBits(mutable random)\012  while (bits < limit) {\012    bits = nextBits(mutable random)\012  }\012  return Some(Int.wrap(U64.wrap(low) + bits % span))\012}\012\012export function nextFloat(mutable random: Random): f64 {\012  const bits = nextBits(mutable random) >> 11\012  return Float.from(bits) / 9007199254740992.0\012}\012\012export function shuffle<T>(mutable random: Random, mutable items: Array<T>) {\012  const length = Arrays.length(items)\012  for (const step of Ranges.upTo(length - 1)) {\012    const position = length - 1 - step\012    if (nextInt(mutable random, 0, position + 1) is Some(other)) {\012      const held = items[position]\012      items[position] = items[other]\012      items[other] = held\012    }\012  }\012}\012"};
