// Map<K, V> with insertion order. emitmaps.nra fills in the @...@ names for
// each map type a program uses.
//
// Entries sit in insertion order in keys, vals, hashes and alive. idx is an
// open-addressing table of entry numbers plus one (0 is an empty slot), twice
// as long as the entries. Removing an entry clears alive and leaves its idx
// slot, so a probe still runs past it. Inserting after a removal appends a new
// entry, which moves the key to the end. When the entries are full they are
// compacted, or doubled when more than half are live.

static M_Map_c5847662* M_Map_c5847662_alloc(int64_t cap) {
  M_Map_c5847662* m = narra_alloc(sizeof(M_Map_c5847662));
  m->rc = 1; m->len = 0; m->used = 0; m->cap = cap; m->mask = cap * 2 - 1;
  m->keys = narra_alloc(sizeof(int64_t) * (size_t)cap);
  m->vals = narra_alloc(sizeof(A_Array_04a1f694*) * (size_t)cap);
  m->hashes = narra_alloc(sizeof(uint64_t) * (size_t)cap);
  m->alive = narra_alloc((size_t)cap);
  m->idx = narra_alloc(sizeof(int64_t) * (size_t)(cap * 2));
  memset(m->idx, 0, sizeof(int64_t) * (size_t)(cap * 2));
  return m;
}
static M_Map_c5847662* M_Map_c5847662_new(int64_t n) {
  int64_t cap = 8;
  while (cap < n) cap *= 2;
  return M_Map_c5847662_alloc(cap);
}
static void M_Map_c5847662_retain(M_Map_c5847662* m) {
  m->rc++;
  NARRA_COPY_SHARED(m);
}
static void M_Map_c5847662_release(M_Map_c5847662* m) {
  NARRA_COPY_DROP(m);
  if (--m->rc == 0) {
    for (int64_t i = 0; i < m->used; i++) {
      if (m->alive[i]) {  A_Array_04a1f694_release(m->vals[i]); }
    }
    narra_free(m->keys); narra_free(m->vals); narra_free(m->hashes);
    narra_free(m->alive); narra_free(m->idx);
    narra_free(m);
  }
}
static uint64_t M_Map_c5847662_hash(int64_t k) {
  uint64_t h = narra_hash_int(k) * UINT64_C(0x9E3779B97F4A7C15);
  return h ^ (h >> 32);
}
// Returns the entry number of k, or -1.
static int64_t M_Map_c5847662_lookup(M_Map_c5847662* m, int64_t k) {
  uint64_t h = M_Map_c5847662_hash(k);
  int64_t i = (int64_t)(h & (uint64_t)m->mask);
  for (;;) {
    int64_t s = m->idx[i];
    if (s == 0) return -1;
    if (m->alive[s - 1] && m->hashes[s - 1] == h && narra_eq_int(m->keys[s - 1], k)) return s - 1;
    i = (i + 1) & m->mask;
  }
}
// Returns a map the caller owns alone, copying it when it is shared.
static M_Map_c5847662* M_Map_c5847662_unique(M_Map_c5847662* m) {
  if (m->rc == 1) return m;
  NARRA_COPY_WRITE(m, 2);
  M_Map_c5847662* c = M_Map_c5847662_alloc(m->cap);
  memcpy(c->keys, m->keys, sizeof(int64_t) * (size_t)m->used);
  memcpy(c->vals, m->vals, sizeof(A_Array_04a1f694*) * (size_t)m->used);
  memcpy(c->hashes, m->hashes, sizeof(uint64_t) * (size_t)m->used);
  memcpy(c->alive, m->alive, (size_t)m->used);
  memcpy(c->idx, m->idx, sizeof(int64_t) * (size_t)(m->cap * 2));
  c->len = m->len; c->used = m->used;
  for (int64_t i = 0; i < c->used; i++) {
    if (c->alive[i]) {  A_Array_04a1f694_retain(c->vals[i]); }
  }
  NARRA_COPY_WRITTEN();
  NARRA_COPY_DROP(m);
  m->rc--;
  return c;
}
// Moves the live entries to the front of arrays of capacity cap.
static void M_Map_c5847662_rebuild(M_Map_c5847662* m, int64_t cap) {
  M_Map_c5847662* n = M_Map_c5847662_alloc(cap);
  int64_t j = 0;
  for (int64_t i = 0; i < m->used; i++) {
    if (!m->alive[i]) continue;
    n->keys[j] = m->keys[i]; n->vals[j] = m->vals[i];
    n->hashes[j] = m->hashes[i]; n->alive[j] = 1;
    int64_t s = (int64_t)(n->hashes[j] & (uint64_t)n->mask);
    while (n->idx[s]) s = (s + 1) & n->mask;
    n->idx[s] = j + 1;
    j++;
  }
  narra_free(m->keys); narra_free(m->vals); narra_free(m->hashes);
  narra_free(m->alive); narra_free(m->idx);
  m->keys = n->keys; m->vals = n->vals; m->hashes = n->hashes;
  m->alive = n->alive; m->idx = n->idx;
  m->cap = cap; m->mask = n->mask; m->used = j;
  narra_free(n);
}
